from ..scanner.arp import ArpScanner


class NetworkScanner(object):
    def scan_network(self, network, timeout):
        """Returns list of available hosts in the scanned network."""
        return ArpScanner().scan_network(network=network, timeout=timeout)

    def scan_hosts(self, hosts, timeout):
        """Returns list of available hosts from specified list."""
        return ArpScanner().scan_hosts(*hosts, timeout=timeout)

    def wait_for_any_host(self, hosts, timeout):
        """Wait until one of specified hosts answer."""
        ArpScanner().wait_for_any_host(*hosts, timeout=timeout)
